'use strict';
(()=>{
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const avatarOK=s=>typeof s==='string'&&s.length<=131094&&/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(s);
 const name=u=>u?.username||u?.email?.split('@')[0]||'Bạn';
 const initials=u=>name(u).split(/[\s._-]+/).filter(Boolean).map(x=>Array.from(x)[0]).slice(0,2).join('').toLocaleUpperCase('vi')||'KH';
 const avatar=(u,cls='')=>`<span class="profile-avatar ${cls}">${avatarOK(u?.avatar)?`<img src="${escape(u.avatar)}" alt="" width="64" height="64">`:`<span aria-hidden="true">${escape(initials(u))}</span>`}</span>`;
 let root,onSaved,state=null,version=0,fileVersion=0;
 const $=s=>root.querySelector(s);
 function init(dialog,saved){root=dialog;onSaved=saved;root.addEventListener('change',e=>{if(e.target.id==='profile-file')choose(e.target.files?.[0]);});root.addEventListener('input',e=>{if(e.target.id==='profile-username'){$('#profile-count').textContent=Array.from(e.target.value).length+'/32';$('#profile-error').textContent='';}});root.addEventListener('click',e=>{const button=e.target.closest('button');if(button?.matches('[data-profile-upload]'))$('#profile-file').click();else if(button?.matches('[data-profile-remove]')&&state&&!state.busy){fileVersion++;state.avatar=null;preview();}else if(button?.matches('[data-profile-skip]'))save(true);});}
 function begin(user,onboarding){version++;state={...user,busy:false,onboarding};return `<div class="profile-banner" aria-hidden="true"><img src="assets/signin-astronaut.png" alt="" width="100" height="100"><span>GÓC HỌC MANG DẤU ẤN CỦA BẠN</span><i>✦</i></div><span class="auth-kicker">${onboarding?'CHÀO MỪNG BẠN ĐẾN KIẾN HỌC':'CÁ NHÂN HOÁ'}</span><h2 id="auth-title">${onboarding?'Một chút về bạn.':'Hồ sơ của bạn.'}</h2><p class="auth-description">Thêm ảnh và chọn tên để góc học gần gũi hơn. Bạn có thể đổi lại bất cứ lúc nào.</p><form id="auth-profile-form"><div class="profile-upload-row"><span id="profile-preview">${avatar(state)}</span><div><strong>Ảnh đại diện</strong><small>JPG, PNG hoặc WebP · tối đa 10 MB</small><small>Ảnh được cắt vuông và thu nhỏ trước khi lưu.</small></div><button type="button" class="profile-upload-button" data-profile-upload>Chọn ảnh</button></div><input id="profile-file" type="file" accept="image/jpeg,image/png,image/webp" hidden><button class="profile-remove" type="button" data-profile-remove ${state.avatar?'':'hidden'}>Gỡ ảnh đại diện</button><label class="auth-field" for="profile-username"><span>Tên hiển thị <small>(username)</small></span><span class="auth-input-shell"><span class="profile-at" aria-hidden="true">@</span><input id="profile-username" name="username" type="text" autocomplete="nickname" placeholder="Ví dụ: Dũng Phạm" minlength="2" maxlength="64" required value="${escape(user.username||'')}" aria-describedby="profile-name-help profile-count"></span></label><div class="profile-input-meta"><small id="profile-name-help">2–32 ký tự. Bạn vẫn đăng nhập bằng email.</small><small id="profile-count">${Array.from(user.username||'').length}/32</small></div><p class="auth-error" id="profile-error" role="alert"></p><button class="auth-primary" type="submit" data-profile-save>${onboarding?'Lưu & bắt đầu học':'Lưu thay đổi'} <span aria-hidden="true">→</span></button></form>${onboarding?'<button type="button" class="auth-switch" data-profile-skip>Để sau, vào học trước</button>':''}`;}
 function preview(){const box=$('#profile-preview');if(!box)return;box.innerHTML=avatar(state);$('[data-profile-remove]').hidden=!state.avatar;$('#profile-file').value='';}
 function busy(value,label){state.busy=value;root.setAttribute('aria-busy',String(value));root.querySelectorAll('#auth-profile-form input,#auth-profile-form button,[data-profile-skip]').forEach(el=>el.disabled=value);$('[data-profile-save]').textContent=label||(state.onboarding?'Lưu & bắt đầu học':'Lưu thay đổi');}
 async function choose(file){if(!file||!state||state.busy)return;const task=++version,selection=++fileVersion;$('#profile-error').textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){$('#profile-error').textContent='Hãy chọn ảnh JPG, PNG hoặc WebP không quá 10 MB.';$('#profile-file').value='';return;}busy(true,'Đang xử lý ảnh…');let image,url;
  try{url=URL.createObjectURL(file);image=new Image();image.src=url;await image.decode();if(task!==version||selection!==fileVersion)return;if(image.naturalWidth*image.naturalHeight>40e6)throw Error('Ảnh quá lớn. Hãy chọn ảnh nhỏ hơn 40 megapixel.');
   const size=Math.min(image.naturalWidth,image.naturalHeight);let result;
   for(const edge of [256,192,128]){const canvas=document.createElement('canvas');canvas.width=canvas.height=edge;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Trình duyệt chưa xử lý được ảnh.');ctx.drawImage(image,(image.naturalWidth-size)/2,(image.naturalHeight-size)/2,size,size,0,0,edge,edge);result=canvas.toDataURL('image/png');canvas.width=canvas.height=0;if(avatarOK(result))break;}
   if(!avatarOK(result))throw Error('Ảnh vẫn quá lớn sau khi thu nhỏ. Hãy chọn ảnh khác.');state.avatar=result;preview();
  }catch(error){if(task===version)$('#profile-error').textContent=error.message||'Không đọc được ảnh. Hãy chọn ảnh khác.';}
  finally{if(url)URL.revokeObjectURL(url);if(task===version&&state){$('#profile-file').value='';busy(false);}}
 }
 async function save(skip=false){if(!state||state.busy)return;if(KienCloud.getUser()?.id!==state.id){$('#profile-error').textContent='Tài khoản đã thay đổi. Hãy đóng và mở lại hồ sơ.';return;}const input=$('#profile-username');if(!skip&&!$('#auth-profile-form').reportValidity())return;const username=input.value.normalize('NFC').trim().replace(/\s+/gu,' ');if(!skip&&(Array.from(username).length<2||Array.from(username).length>32||!/^[\p{L}\p{M}\p{N} _.\-]+$/u.test(username))){$('#profile-error').textContent='Tên cần 2–32 ký tự: chữ, số, dấu cách, dấu chấm, gạch dưới hoặc gạch ngang.';input.focus();return;}
  const task=++version,owner=state.id;busy(true,skip?'Đang tiếp tục…':'Đang lưu hồ sơ…');$('#profile-error').textContent='';
  try{const result=await KienCloud.api('/auth/profile',{expectedRevision:state.profileRevision||0,...(skip?{skip:true}:{username,avatar:state.avatar||null})},true);if(KienCloud.getUser()?.id===owner)KienCloud.updateUser(result.user);if(task===version&&root.open)onSaved(skip);}
  catch(error){if(task!==version)return;if(error.status===409&&error.data?.user){KienCloud.updateUser(error.data.user);state={...state,...error.data.user};input.value=state.username;preview();$('#profile-count').textContent=Array.from(state.username).length+'/32';}$('#profile-error').textContent=error.message;}
  finally{if(task===version&&state)busy(false);}
 }
 function reset(){version++;fileVersion++;state=null;}
 window.KienProfile={init,begin,save,reset,avatar,name,initials};
})();
